/* Table, not flexbox - wkhtmltopdf's flex support is unreliable enough
   that light text on this dark background was rendering black in the
   actual PDF export (fine in an HTML/Chromium preview, broken in the real
   "Get PDF" output). Tables are the standard reliable layout primitive for
   wkhtmltopdf. */
.ns-header {
  background: #161b33;
  color: #fff !important;
  padding: 18px 24px 14px;
  border-collapse: collapse;
  table-layout: fixed;
}

.ns-header-left {
  vertical-align: top;
  text-align: left;
  width: 62%;
}

.ns-company {
  font-size: 18px;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: #f0c419 !important;
  white-space: nowrap;
}

.ns-tagline {
  font-size: 11px;
  letter-spacing: 0.12em;
  color: #94a3b8 !important;
  margin-top: 4px;
}

.ns-header-contact {
  vertical-align: top;
  text-align: right;
  font-size: 10px;
  color: #cbd5e1 !important;
  line-height: 1.6;
  width: 38%;
}

.ns-title-bar {
  background: #f0c419;
  color: #161b33;
  padding: 10px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.ns-title {
  font-size: 20px;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.ns-title-right {
  text-align: right;
}

.ns-doc-no {
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
}

/* Inline now (doc number + date on one line) instead of a stacked block
   below it - shrinks .ns-title-right down to a single line tall, which
   in turn lets the whole title-bar (height driven by its tallest child
   under flex align-items:center) sit shorter instead of being forced tall
   enough for two stacked lines. */
.ns-doc-date {
  font-size: 10px;
  font-weight: 400;
  color: #4b3d06;
}

/* Table, not CSS Grid/Flexbox - wkhtmltopdf's support for both is
   unreliable enough that the two cards (and each card's own label/value
   rows) rendered stacked instead of side-by-side in the actual PDF
   export (fine-looking markup, broken real output - same class of issue
   .ns-header's own comment above already flagged, just not yet applied
   here). Table-based two-card layout, same pattern as Purchase Invoice
   Print's pip-info-grid/Purchase Order Print's pop-info-cell: a wrapping
   <div> carries the calc() width, a plain width:100% table-layout:fixed
   inner table holds the two card cells (calc()+table-layout:fixed on the
   SAME element is its own separate unreliable combination). */
.ns-info-grid-wrap {
  margin: 14px 24px 0;
  width: calc(100% - 48px);
}

.ns-info-grid {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.ns-info-cell {
  width: 48%;
  vertical-align: top;
}

.ns-info-gap {
  width: 4%;
}

.ns-info-box {
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 10px 14px;
}

.ns-info-title {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: #94a3b8;
  padding-bottom: 5px;
  margin-bottom: 5px;
  border-bottom: 1px solid #eef1f5;
}

.ns-info-table {
  border-collapse: collapse;
  width: 100%;
  table-layout: fixed;
}

.ns-info-table td {
  vertical-align: top;
  padding: 2px 0;
}

/* white-space:nowrap keeps the label itself from wrapping; the value
   column gets overflow:hidden + text-overflow:ellipsis as a safety net
   (truncate rather than wrap and break the card's height) for the rare
   name/address too long for the column - the label width below is sized
   to leave the value column as much room as the two-card layout allows. */
.ns-info-label {
  width: 62px;
  color: #94a3b8;
  font-size: 10px;
  white-space: nowrap;
}

.ns-info-value {
  font-size: 12px;
  color: #0f172a;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ns-section-title {
  margin: 16px 24px 8px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: #94a3b8;
}

/* calc() width directly on the table (no wrapping div) is the same
   unreliable combination flagged elsewhere in this file - it silently
   failed here, and without table-layout:fixed the table then fell back
   to sizing itself off its own content (the short "Jasa GANTI BAN"/"AKI
   45AH" text), rendering barely half the page wide instead of filling
   it. Wrapping div carries the calc() width; the inner table is a plain
   width:100% table-layout:fixed so the one column with no explicit width
   (Uraian) gets whatever's left over instead of shrink-wrapping. */
.ns-items-table-wrap {
  margin: 0 24px;
  width: calc(100% - 48px);
}

.ns-items-table {
  width: 100%;
  table-layout: fixed;
  border-collapse: collapse;
}

.ns-items-table thead tr {
  background: #161b33;
  color: #fff;
}

.ns-items-table th {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 6px 10px;
  text-align: left;
}

.ns-col-no {
  width: 32px;
}

.ns-col-qty {
  width: 50px;
}

.ns-col-subtotal {
  width: 110px;
}

.ns-items-table td {
  padding: 7px 10px;
  font-size: 11px;
  border-bottom: 1px solid #eef1f5;
  vertical-align: top;
}

.ns-row-alt {
  background: #fafaf5;
}

.ns-item-name {
  font-weight: 700;
}

.ns-item-desc {
  font-size: 9.5px;
  color: #94a3b8;
  margin-top: 2px;
}

.text-right {
  text-align: right;
}

/* Right-aligned under the items table's own Subtotal column - same
   spacer-cell technique as Purchase Order Print's pop-summary-align
   (margin-left:auto on a plain block doesn't reliably right-align under
   wkhtmltopdf either, and .ns-summary-row's own display:flex +
   justify-content:space-between rendered label/value stacked instead of
   on one line, same as the info cards above). */
.ns-summary-align-wrap {
  margin: 10px 24px 0;
  width: calc(100% - 48px);
}

.ns-summary-align {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.ns-summary-spacer {
  width: 55%;
}

.ns-summary-col {
  width: 45%;
  vertical-align: top;
}

.ns-summary-rows {
  border-collapse: collapse;
}

.ns-summary-rows td {
  padding: 5px 4px;
  font-size: 11px;
  color: #475569;
}

/* Table, not flexbox - see .ns-header's comment above for why. */
.ns-summary-total {
  background: #161b33;
  color: #f0c419 !important;
  padding: 8px 12px;
  margin-top: 4px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 800;
  line-height: 1.15;
  border-collapse: collapse;
}

.ns-summary-total td {
  color: #f0c419 !important;
  white-space: nowrap;
}

.ns-notes-title {
  margin: 14px 24px 6px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: #94a3b8;
}

.ns-notes-box {
