  letter-spacing: 0.05em;
  font-size: 9px;
  font-weight: 700;
  /* Header text is bold+uppercase+letter-spaced, which renders visibly
     WIDER than the plain digits/dates in the body below - "No" fit fine
     as row data at the old 10px horizontal padding, but the header "NO"
     itself was already eating past the 34px column width before the
     text-overflow:ellipsis even had a chance, cutting it to nothing.
     Tightened here instead of only widening the column, since the same
     padding was eating into every other narrow column's headroom too. */
  padding: 8px 6px;
  text-align: left;
}

.bsi-table thead th.num,
