/* Wrap-div split, same reason as .pop-items-table-wrap in Purchase Order
   Print: calc() + table-layout:fixed on the SAME <table> is unreliable in
   wkhtmltopdf. table-layout:fixed is what actually makes "Nama Item" (the
   only column with no explicit width) take up the real remaining width
   instead of being sized by content - without it the whole table
   rendered narrower than its calc()'d width and wrapped item names that
   had plenty of room. */
.prp-items-table-wrap {
  margin: 0 12mm;
  width: calc(100% - 24mm);
}

.prp-items-table {
  width: 100%;
  table-layout: fixed;
  border-collapse: collapse;
}

.prp-items-table thead tr {
  background: #161b33;
  color: #fff;
}

.prp-items-table th {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 8px 10px;
  text-align: left;
}

.prp-col-no {
  width: 32px;
}

.prp-col-qty {
  width: 65px;
}

.prp-col-uom {
  width: 55px;
}

.prp-col-status {
  width: 90px;
}

.prp-items-table td {
  padding: 10px;
  font-size: 11px;
  border-bottom: 1px solid #eef1f5;
  vertical-align: top;
}

.prp-row-alt {
  background: #fafaf5;
}

.prp-item-name {
  font-weight: 700;
}

.prp-item-desc {
  font-size: 9.5px;
  color: #94a3b8;
  margin-top: 2px;
}

.text-right {
  text-align: right;
}

.prp-badge {
  display: inline-block;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 2px 8px;
  border-radius: 4px;
  background: #e2e8f0;
  color: #475569 !important;
}

.prp-badge-lengkap {
  background: #dcfce7;
  color: #15803d !important;
}

.prp-badge-partial {
  background: #fef9c3;
  color: #a16207 !important;
}

.prp-badge-belum {
  background: #f1f5f9;
  color: #64748b !important;
}

.prp-signatures-wrap {
  width: calc(100% - 24mm);
  margin: 0 12mm;
  padding-bottom: 24px;
}

.prp-signatures {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.prp-sig {
  width: 33.33%;
  vertical-align: top;
  padding-right: 24px;
}

.prp-sig-title {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: #94a3b8;
  margin-bottom: 40px;
}

.prp-sig-line {
  border-bottom: 1px solid #94a3b8;
  margin-bottom: 6px;
}

.prp-sig-name {
  font-size: 11px;
  color: #475569;
}

#header-html,
#footer-html,
.print-heading,
.print-format .page-header,
.print-format .page-footer,
.page-header,
.page-footer,
#page-header,
#page-footer {
  display: none !important;
}

/* Monospace throughout, matching the approved mockup - a deliberately
   different look from Purchase Order/Receipt Print's Inter/sans-serif
   style, not a mistake. */
.print-format.pip-format {
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, Courier, monospace;
  color: #0f172a;
  font-size: 11px;
  margin: 0;
  padding: 0 !important;
}

/* Plain, exact ".print-format" selector - see Purchase Order Print's own
   CSS for the full explanation of why this exact (non-compound) selector
   is what actually reaches wkhtmltopdf's own --margin-left/--margin-right
   flags (frappe/utils/pdf.py's get_print_format_styles()). */
.print-format {
  margin-left: 0mm;
  margin-right: 0mm;
}

@page {
  margin: 0mm;
}

.print-format * {
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.pip-items-table thead {
  display: table-header-group;
}

.pip-items-table tr {
  page-break-inside: avoid;
}

/* Bottom-pinned signature block - same estimate-based technique as
   Purchase Order/Receipt Print (see purchase_order_print's own CSS
   comment for the full history of what was tried and reverted before
   landing on this). */
.pip-sign-block {
  page-break-inside: avoid;
  display: table;
  width: 100%;
}

.pip-sign-block-inner {
  display: table-cell;
  vertical-align: bottom;
}

.pip-sign-block-forced-page {
  page-break-before: always;
}

.pip-page-number {
  text-align: center;
  font-size: 9px;
  color: #94a3b8;
  margin: 0;
  padding: 4px 0;
}

/* Table-based layout throughout - see Purchase Order Print's own CSS
   comment: wkhtmltopdf's Qt WebKit engine doesn't reliably support CSS
   Grid/Flexbox, tables are the one layout primitive it gets right. */
.pip-header {
  background: #161b33;
  color: #fff !important;
  padding: 28px 12mm 20px;
  border-collapse: collapse;
  table-layout: fixed;
}

.pip-header-left {
  vertical-align: top;
  text-align: left;
  width: 62%;
}

.pip-company {
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #f0c419 !important;
  white-space: nowrap;
}

.pip-tagline {
  font-size: 10.5px;
  letter-spacing: 0.06em;
  color: #94a3b8 !important;
  margin-top: 4px;
}

.pip-header-contact {
  vertical-align: top;
  text-align: right;
  font-size: 10px;
  color: #cbd5e1 !important;
  line-height: 1.6;
  width: 38%;
}

.pip-title-bar {
  background: #8a4a1f;
  color: #fff;
  border-collapse: collapse;
}

.pip-title-bar td {
  vertical-align: middle;
  padding: 16px 12mm;
}

.pip-title {
  font-size: 19px;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: 0.02em;
  color: #fdf1de !important;
}

.pip-title-right {
  text-align: right;
}

.pip-doc-no {
  font-size: 12.5px;
  font-weight: 700;
  color: #fdf1de !important;
}

.pip-doc-date {
  font-size: 10px;
  color: #f0d9bd !important;
  margin-top: 2px;
}

/* calc() lives on the wrapping <div>, plain width:100% + table-layout:
   fixed on the inner <table> - see Purchase Order Print's own CSS for
   why calc() + table-layout:fixed on the SAME element is unreliable in
   wkhtmltopdf. */
.pip-info-grid-wrap {
